const item = $input.item.json;

// Deterministischer Dummy: simuliert die spätere Agentenantwort, ohne echte
// Qlik-Analyse, Websuche oder ein LLM zu verwenden. Der Dummy erfüllt bereits
// den Ausgabevertrag (diagnosis/requiredProfile/shortlist/recommendation),
// damit die Struktur später ohne Änderungen an Formular, Validierung oder
// Ergebnisdarstellung durch den echten AI Agent befüllt werden kann.
const agentResponse = {
  simulated: true,
  diagnosis: {
    summary: `Simulierte Analyse für ${item.club}: ${item.objective}`,
    evidence: [
      'Dummy-Datenpunkt 1 (keine echte Qlik-Analyse durchgeführt)',
      'Dummy-Datenpunkt 2 (keine echte Websuche durchgeführt)'
    ],
    hypotheses: [
      'Simulierte Hypothese A zur sportlichen Situation',
      'Simulierte Hypothese B zur sportlichen Situation'
    ],
    uncertainties: [
      'Es wurden keine echten Daten verwendet, die Ausgabe ist rein simuliert.'
    ]
  },
  requiredProfile: {
    position: 'Simulierte Position',
    role: 'Simulierte taktische Rolle',
    criteria: ['Simuliertes Kriterium 1', 'Simuliertes Kriterium 2']
  },
  shortlist: [
    { name: 'Dummy-Spieler A', note: 'Platzhalter, keine echte Kandidat:innen-Recherche' },
    { name: 'Dummy-Spieler B', note: 'Platzhalter, keine echte Kandidat:innen-Recherche' }
  ],
  recommendation: {
    candidate: 'Dummy-Spieler A',
    reasoning: 'Simulierte Begründung ohne echte Analyse oder Recherche.',
    risks: ['Simuliertes Risiko, das bei einer echten Analyse zu prüfen wäre'],
    nextStep: 'Nächster Schritt: den Dummy durch den echten AI Agent ersetzen.'
  }
};

return [{ json: { ...item, agentResponse } }];

const item = $input.item.json;
const response = item.agentResponse;
const errors = [];

if (!response || typeof response !== 'object') {
  errors.push("agentResponse fehlt oder ist kein Objekt.");
} else {
  const d = response.diagnosis;
  if (!d || typeof d.summary !== 'string' || !d.summary) errors.push('diagnosis.summary fehlt.');
  if (!d || !Array.isArray(d.evidence)) errors.push('diagnosis.evidence fehlt oder ist kein Array.');
  if (!d || !Array.isArray(d.hypotheses)) errors.push('diagnosis.hypotheses fehlt oder ist kein Array.');
  if (!d || !Array.isArray(d.uncertainties)) errors.push('diagnosis.uncertainties fehlt oder ist kein Array.');

  const p = response.requiredProfile;
  if (!p || !p.position) errors.push('requiredProfile.position fehlt.');
  if (!p || !p.role) errors.push('requiredProfile.role fehlt.');
  if (!p || !Array.isArray(p.criteria)) errors.push('requiredProfile.criteria fehlt oder ist kein Array.');

  if (!Array.isArray(response.shortlist)) errors.push('shortlist fehlt oder ist kein Array.');

  const r = response.recommendation;
  if (!r || !r.candidate) errors.push('recommendation.candidate fehlt.');
  if (!r || !r.reasoning) errors.push('recommendation.reasoning fehlt.');
  if (!r || !Array.isArray(r.risks)) errors.push('recommendation.risks fehlt oder ist kein Array.');
  if (!r || !r.nextStep) errors.push('recommendation.nextStep fehlt.');
}

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Die Agentenantwort ist ungültig und wird nicht als fachliche Empfehlung angezeigt.\n\n' + errors.join('\n')
  }
}];

const item = $input.item.json;
const rawMessage = (item && item.error && item.error.message) ? item.error.message : 'Unbekannter Fehler';

return [{
  json: {
    ...item,
    errorMessage: 'Bei der Kommunikation mit dem lokalen Ollama-Modell ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.\n\nDetails: ' + rawMessage
  }
}];
